import React, { useEffect, useState } from "react";
import { getUserProfile } from "../api/auth";
import { getAllBookings } from "../api/fastapi";
import { Button } from "../components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card";
import { Badge } from "../components/ui/badge";
import { createBooking, checkAvailability } from "../api/fastapi";

export default function UserDashboard() {
  const [user, setUser] = useState(null);
  const [userBookings, setUserBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("bookings"); // "bookings" or "newBooking"
  
  // Booking form states
  const [searchResults, setSearchResults] = useState(null);
  const [availabilityData, setAvailabilityData] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [bookingLoading, setBookingLoading] = useState(false);
  const [bookingStep, setBookingStep] = useState("search");
  const [guestDetails, setGuestDetails] = useState({
    guest_name: "",
    guest_email: "",
    guest_phone: ""
  });

  useEffect(() => {
    const token = localStorage.getItem("accessToken");
    if (!token) {
      window.location.href = "/login";
      return;
    }
    fetchUserData();
    fetchUserBookings();
  }, []);

  const fetchUserData = async () => {
    try {
      const response = await getUserProfile();
      setUser(response.data);
    } catch (error) {
      console.error("Failed to fetch user data:", error);
    }
  };

  const fetchUserBookings = async () => {
    try {
      const response = await getAllBookings();
      setUserBookings(response.data || []);
    } catch (error) {
      console.error("Failed to fetch bookings:", error);
      setUserBookings([]);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("accessToken");
    window.location.href = "/login";
  };

  const handleSearch = async (filters) => {
    if (!filters.destination || !filters.startDate || !filters.endDate) {
      setError("Please fill in destination, check-in and check-out dates");
      return;
    }

    setBookingLoading(true);
    setError("");
    setSearchResults(filters);

    try {
      const checkInDate = filters.startDate.toISOString().split('T')[0];
      const checkOutDate = filters.endDate.toISOString().split('T')[0];

      const response = await checkAvailability(
        checkInDate,
        checkOutDate,
        filters.destination
      );
      
      setAvailabilityData(response.data);
      if (response.data.available) {
        setBookingStep("details");
      }
    } catch (err) {
      setError(err.response?.data?.detail || "Failed to check availability");
      setAvailabilityData(null);
    } finally {
      setBookingLoading(false);
    }
  };

  const handleGuestDetailsChange = (e) => {
    setGuestDetails({
      ...guestDetails,
      [e.target.name]: e.target.value
    });
  };

  const handleCreateBooking = async () => {
    if (!guestDetails.guest_name || !guestDetails.guest_email) {
      setError("Please fill in name and email");
      return;
    }

    setBookingLoading(true);
    setError("");

    try {
      const bookingData = {
        check_in_date: searchResults.startDate.toISOString().split('T')[0],
        check_out_date: searchResults.endDate.toISOString().split('T')[0],
        destination: searchResults.destination,
        guest_name: guestDetails.guest_name,
        guest_email: guestDetails.guest_email,
        guest_phone: guestDetails.guest_phone || null
      };

      const response = await createBooking(bookingData);
      setSuccess(`Booking created successfully! Booking ID: ${response.data.id}`);
      setBookingStep("confirm");
      
      // Refresh bookings list
      fetchUserBookings();
      
      // Reset form after success
      setTimeout(() => {
        setBookingStep("search");
        setSearchResults(null);
        setAvailabilityData(null);
        setGuestDetails({ guest_name: "", guest_email: "", guest_phone: "" });
        setSuccess("");
        setActiveTab("bookings"); // Switch back to bookings tab
      }, 3000);

    } catch (err) {
      setError(err.response?.data?.detail || "Failed to create booking");
    } finally {
      setBookingLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-orange-100 via-orange-200 to-orange-300 dark:from-orange-950 dark:via-orange-900 dark:to-orange-800">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-orange-600"></div>
          <p className="mt-2 text-muted-foreground">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-100 via-orange-200 to-orange-300 dark:from-orange-950 dark:via-orange-900 dark:to-orange-800 py-8">
      <div className="max-w-6xl mx-auto px-4">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-4xl font-bold text-orange-700 dark:text-orange-400" style={{ fontFamily: 'Playfair Display, Georgia, serif' }}>
              Welcome, {user?.username || 'User'}!
            </h1>
            <p className="text-lg text-muted-foreground mt-2" style={{ fontFamily: 'Crimson Text, Georgia, serif' }}>
              Manage your bookings and plan your next adventure
            </p>
          </div>
          <Button 
            onClick={handleLogout}
            variant="outline"
            className="bg-red-600 text-white hover:bg-red-700"
          >
            Logout
          </Button>
        </div>

        {/* Navigation Tabs */}
        <div className="flex gap-4 mb-6">
          <Button
            onClick={() => setActiveTab("bookings")}
            variant={activeTab === "bookings" ? "default" : "outline"}
            className={activeTab === "bookings" ? "bg-orange-600 text-white" : ""}
          >
            My Bookings ({userBookings.length})
          </Button>
          <Button
            onClick={() => {
              setActiveTab("newBooking");
              setBookingStep("search");
              setError("");
              setSuccess("");
            }}
            variant={activeTab === "newBooking" ? "default" : "outline"}
            className={activeTab === "newBooking" ? "bg-orange-600 text-white" : ""}
          >
            Create New Booking
          </Button>
        </div>

        {/* Content */}
        {activeTab === "bookings" && (
          <div className="space-y-4">
            <h2 className="text-2xl font-semibold text-orange-700 dark:text-orange-400">Your Bookings</h2>
            {userBookings.length === 0 ? (
              <Card>
                <CardContent className="p-8 text-center">
                  <p className="text-muted-foreground text-lg">No bookings found</p>
                  <Button
                    onClick={() => setActiveTab("newBooking")}
                    className="mt-4 bg-gradient-to-r from-orange-500 to-red-600 text-white"
                  >
                    Create Your First Booking
                  </Button>
                </CardContent>
              </Card>
            ) : (
              <div className="grid gap-4">
                {userBookings.map((booking) => (
                  <Card key={booking.id}>
                    <CardHeader>
                      <div className="flex justify-between items-start">
                        <CardTitle className="text-xl">{booking.destination}</CardTitle>
                        <Badge variant={booking.status === 'confirmed' ? 'default' : 'secondary'}>
                          {booking.status}
                        </Badge>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                        <div>
                          <p className="font-medium text-muted-foreground">Check-in</p>
                          <p>{booking.check_in_date}</p>
                        </div>
                        <div>
                          <p className="font-medium text-muted-foreground">Check-out</p>
                          <p>{booking.check_out_date}</p>
                        </div>
                        <div>
                          <p className="font-medium text-muted-foreground">Guest Name</p>
                          <p>{booking.guest_name}</p>
                        </div>
                        <div>
                          <p className="font-medium text-muted-foreground">Booking ID</p>
                          <p className="font-mono text-xs">{booking.id}</p>
                        </div>
                      </div>
                      {booking.guest_phone && (
                        <div className="mt-2">
                          <p className="font-medium text-muted-foreground">Phone</p>
                          <p>{booking.guest_phone}</p>
                        </div>
                      )}
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === "newBooking" && (
          <div>
            <h2 className="text-2xl font-semibold text-orange-700 dark:text-orange-400 mb-6">Create New Booking</h2>
            
            {/* Search Step */}
            {bookingStep === "search" && (
              <div>
                <Card>
                  <CardHeader>
                    <CardTitle>Book Your Perfect Journey</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div>
                      <label className="block mb-1 text-sm font-medium text-muted-foreground">Destination *</label>
                      <input
                        type="text"
                        placeholder="Enter destination (e.g., Ladakh, Manali)"
                        value={searchResults?.destination || ""}
                        onChange={(e) => setSearchResults(prev => ({ ...prev, destination: e.target.value }))}
                        className="w-full px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-orange-400 bg-background text-foreground"
                      />
                    </div>
                    
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block mb-1 text-sm font-medium text-muted-foreground">Check-in Date *</label>
                        <input
                          type="date"
                          value={searchResults?.startDate?.toISOString().split('T')[0] || ""}
                          onChange={(e) => {
                            const date = new Date(e.target.value);
                            setSearchResults(prev => ({ ...prev, startDate: date }));
                          }}
                          min={new Date().toISOString().split('T')[0]}
                          className="w-full px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-orange-400 bg-background text-foreground"
                        />
                      </div>
                      
                      <div>
                        <label className="block mb-1 text-sm font-medium text-muted-foreground">Check-out Date *</label>
                        <input
                          type="date"
                          value={searchResults?.endDate?.toISOString().split('T')[0] || ""}
                          onChange={(e) => {
                            const date = new Date(e.target.value);
                            setSearchResults(prev => ({ ...prev, endDate: date }));
                          }}
                          min={searchResults?.startDate?.toISOString().split('T')[0] || new Date().toISOString().split('T')[0]}
                          className="w-full px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-orange-400 bg-background text-foreground"
                        />
                      </div>
                    </div>
                    
                    <Button
                      onClick={() => {
                        if (!searchResults?.destination || !searchResults?.startDate || !searchResults?.endDate) {
                          setError("Please fill in all required fields");
                          return;
                        }
                        handleSearch(searchResults);
                      }}
                      className="w-full bg-gradient-to-r from-orange-500 to-red-600 text-white"
                      disabled={bookingLoading}
                    >
                      {bookingLoading ? "Checking Availability..." : "Check Availability"}
                    </Button>
                  </CardContent>
                </Card>
                
                {availabilityData && !availabilityData.available && (
                  <Card className="mt-6">
                    <CardContent className="p-6">
                      <div className="text-center">
                        <div className="text-red-600 text-lg font-semibold mb-2">❌ Not Available</div>
                        <p className="text-muted-foreground">{availabilityData.message}</p>
                        <Button 
                          className="mt-4" 
                          onClick={() => {
                            setAvailabilityData(null);
                            setSearchResults(null);
                          }}
                        >
                          Try Different Dates
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                )}
              </div>
            )}

            {/* Guest Details Step */}
            {bookingStep === "details" && availabilityData?.available && (
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle className="text-green-600">✅ Available for Booking!</CardTitle>
                  <div className="space-y-2 text-sm text-muted-foreground">
                    <p><strong>Destination:</strong> {availabilityData.destination}</p>
                    <p><strong>Check-in:</strong> {availabilityData.check_in_date}</p>
                    <p><strong>Check-out:</strong> {availabilityData.check_out_date}</p>
                    <p><strong>Nights:</strong> {availabilityData.nights}</p>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  <h3 className="text-lg font-semibold">Guest Details</h3>
                  
                  <div>
                    <label className="block mb-1 text-sm font-medium text-muted-foreground">Full Name *</label>
                    <input
                      type="text"
                      name="guest_name"
                      value={guestDetails.guest_name}
                      onChange={handleGuestDetailsChange}
                      required
                      className="w-full px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-orange-400 bg-background text-foreground"
                    />
                  </div>
                  
                  <div>
                    <label className="block mb-1 text-sm font-medium text-muted-foreground">Email Address *</label>
                    <input
                      type="email"
                      name="guest_email"
                      value={guestDetails.guest_email}
                      onChange={handleGuestDetailsChange}
                      required
                      className="w-full px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-orange-400 bg-background text-foreground"
                    />
                  </div>
                  
                  <div>
                    <label className="block mb-1 text-sm font-medium text-muted-foreground">Phone Number (Optional)</label>
                    <input
                      type="tel"
                      name="guest_phone"
                      value={guestDetails.guest_phone}
                      onChange={handleGuestDetailsChange}
                      className="w-full px-4 py-2 rounded-lg border border-border focus:outline-none focus:ring-2 focus:ring-orange-400 bg-background text-foreground"
                    />
                  </div>

                  <div className="flex gap-4 pt-4">
                    <Button
                      variant="outline"
                      onClick={() => setBookingStep("search")}
                      className="flex-1"
                    >
                      Back to Search
                    </Button>
                    <Button
                      onClick={handleCreateBooking}
                      disabled={bookingLoading}
                      className="flex-1 bg-gradient-to-r from-orange-500 to-red-600 text-white"
                    >
                      {bookingLoading ? "Creating Booking..." : "Confirm Booking"}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            )}

            {/* Success Step */}
            {bookingStep === "confirm" && success && (
              <Card className="mt-6">
                <CardContent className="p-8 text-center">
                  <div className="text-green-600 text-6xl mb-4">✅</div>
                  <h2 className="text-2xl font-bold text-green-600 mb-2">Booking Confirmed!</h2>
                  <p className="text-muted-foreground mb-4">{success}</p>
                  <p className="text-sm text-muted-foreground">Redirecting to your bookings...</p>
                </CardContent>
              </Card>
            )}

            {/* Error Display */}
            {error && (
              <Card className="mt-6 border-red-200">
                <CardContent className="p-4">
                  <div className="text-red-600 font-medium text-center">{error}</div>
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
